// Actor model simulation in Node.js using worker_threads
// Each Worker = one actor with isolated private state
// Communication is exclusively via postMessage (message passing)

const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

if (isMainThread) {
  // ---- SUPERVISOR (one-for-one strategy) ----
  function spawnSupervised(id, initialCount, maxRestarts = 3) {
    let restarts = 0;
    const ref = { worker: null, send: (msg) => ref.worker.postMessage(msg) };

    function start() {
      ref.worker = new Worker(__filename, { workerData: { id, count: initialCount } });
      ref.worker.on('message', (msg) => console.log(`[Supervisor] ${id} replied:`, msg));
      ref.worker.on('error', (err) => {
        console.error(`[Supervisor] ${id} CRASHED: ${err.message}`);
        if (++restarts > maxRestarts) {
          console.error(`[Supervisor] ${id}: restart limit reached — escalating`);
          return;
        }
        start(); // restart ONLY this actor, with fresh initial state
        console.log(`[Supervisor] ${id} restarted (restart #${restarts})`);
      });
    }

    start();
    return ref; // a stable "address": callers keep using ref.send() across restarts
  }

  const counterA = spawnSupervised('A', 0);
  const counterB = spawnSupervised('B', 1000);

  // Message passing: asynchronous fire-and-forget — the sender never blocks
  counterA.send({ type: 'INCREMENT', amount: 5 });
  counterA.send({ type: 'INCREMENT', amount: 3 });
  counterA.send({ type: 'GET' });                     // → { id: 'A', count: 8 }
  counterB.send({ type: 'DECREMENT', amount: 200 });
  counterB.send({ type: 'GET' });                     // → { id: 'B', count: 800 }

  // Crash isolation: B crashing does not affect A
  setTimeout(() => {
    counterB.send({ type: 'CRASH' });                 // B throws and dies
    counterA.send({ type: 'INCREMENT', amount: 1 });
    counterA.send({ type: 'GET' });                   // → { id: 'A', count: 9 }
  }, 100);

  // After the restart, B is back — with its initial state, not 800
  setTimeout(() => counterB.send({ type: 'GET' }), 300); // → { id: 'B', count: 1000 }

  setTimeout(() => { counterA.worker.terminate(); counterB.worker.terminate(); }, 500);

} else {
  // ---- ACTOR BODY: runs inside a Worker thread ----
  // Private state — ONLY this actor can read or write it
  let state = { count: workerData.count };

  parentPort.on('message', (msg) => {
    // Messages are handled one at a time, in arrival order — no concurrent access
    switch (msg.type) {
      case 'INCREMENT':
        state.count += msg.amount;   // no reply needed — fire-and-forget mutation
        break;
      case 'DECREMENT':
        state.count -= msg.amount;
        break;
      case 'GET':
        // postMessage structured-clones the object: the receiver gets a COPY
        parentPort.postMessage({ id: workerData.id, count: state.count });
        break;
      case 'CRASH':
        // Unexpected condition: don't patch things up locally — let it crash
        throw new Error(`Actor ${workerData.id} hit an unexpected condition`);
    }
  });
}

// Contrasting shared memory (unsafe) vs message passing (safe)
// Run this in Node.js to see the difference

// ---- SHARED MEMORY: data race without Atomics ----
// Two workers incrementing the same SharedArrayBuffer counter concurrently
// WITHOUT synchronization → result is wrong (race condition)
const sharedBuf = new SharedArrayBuffer(4);
const shared = new Int32Array(sharedBuf);
shared[0] = 0;

// Simulated race (conceptual — actual race needs two workers):
// Thread A: reads shared[0] = 0
// Thread B: reads shared[0] = 0 (before A writes)
// Thread A: writes shared[0] = 1
// Thread B: writes shared[0] = 1  ← LOST UPDATE
// Final: 1, not 2

// ---- SHARED MEMORY: safe with Atomics ----
Atomics.add(shared, 0, 1); // atomic read-modify-write
Atomics.add(shared, 0, 1);
console.log('Shared counter (atomic):', Atomics.load(shared, 0)); // 2 ✓
// Correct but: you must use Atomics EVERYWHERE that touches this memory
// Forget once → silent corruption

// ---- MESSAGE PASSING: structurally safe, no Atomics needed ----
function createCounterActor() {
  // Private state: ONLY this closure can read or write `count`
  let count = 0;

  // Message handler — processes one message at a time
  return function handleMessage(msg) {
    switch (msg.type) {
      case 'increment': count += msg.amount; return null;
      case 'decrement': count -= msg.amount; return null;
      case 'get':       return { count }; // returns a COPY, not a reference
      case 'reset':     count = 0; return null;
    }
  };
}

const counter = createCounterActor();
counter({ type: 'increment', amount: 5 });
counter({ type: 'increment', amount: 3 });
const result = counter({ type: 'get' });
console.log('Actor counter:', result.count); // always 8, no race possible

// Even if two 'senders' call handleMessage: in real actor runtimes, the
// mailbox serializes delivery — only one message runs at a time.
// The sequential guarantee is enforced by the runtime, not the programmer.
